package diff

// Hunk is one contiguous run of changed lines.
type Hunk struct {
	Start int
	Count int
}

// ContextAfter returns up to n lines of trailing context for h.
// The window must stop at the last line of the file.
func ContextAfter(lines []string, h Hunk, n int) []string {
	first := h.Start + h.Count
	last := first + n
	if last >= len(lines) {
		last = len(lines) + 1
	}
	if first >= last {
		return nil
	}
	return lines[first:last]
}
